  const [modeDrawer,setModeDrawer]=useState(false)
  const [apiNotice,setApiNotice]=useState("正在读取榜单数据…")
  const fallbackCandidates=[["Bobber Thermal Mug, 0.77 L","Bobber","家居生活 · 保温杯","5,168","12.3%","55.9%","https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=160&h=160&fit=crop&auto=format"],["SoundPro X1 Wireless Headphones","SoundPro","电子产品 · 耳机","4,782","18.6%","42.8%","https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=160&h=160&fit=crop&auto=format"],["Smart Living Desk Lamp","Lumen","家居生活 · 照明","3,945","9.8%","38.4%","https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=160&h=160&fit=crop&auto=format"]]
  const [candidates,setCandidates]=useState<string[][]>(fallbackCandidates)
  const categories=[["大盘总览","全类目市场趋势"],["类目分析","细分赛道洞察"],["热销产品","全站热度排行"],["中国储热销","中国仓现货机会"],["热词精选","高意图搜索词"],["标签反查","以品找词与标签"],["WB热销","Wildberries 热榜"]]
  useEffect(()=>{let live=true;api.get<unknown>("/analytics/bestsellers").then(payload=>{const data=payload as {items?:unknown[];data?:unknown[]};const rows=Array.isArray(payload)?payload:(data.items||data.data||[]);const parsed=rows.map((row,index)=>{const item=row as Record<string,unknown>;return [String(item.title||item.product_name||item.name||`市场商品 ${index+1}`),String(item.brand||"—"),String(item.category_name||item.category||"Ozon 市场"),String(item.sales_amount||item.revenue||"—"),String(item.sales_growth||item.growth||"—"),String(item.click_rate||item.ctr||"—"),String(item.image_url||item.image||fallbackCandidates[index%fallbackCandidates.length][6])]}).filter(x=>x[0]);if(live&&parsed.length){setCandidates(parsed);setApiNotice(`已接入榜单 API · ${parsed.length} 条实时记录`)}else if(live)setApiNotice("榜单暂无可展示记录，当前显示示例数据")}).catch(error=>{if(live)setApiNotice(error instanceof ApiError&&error.status===401?"请登录后读取实时榜单，当前显示示例数据":"榜单 API 暂不可用，当前显示示例数据")});return()=>{live=false}},[])
  const addToCollection=(item:string[])=>setApiNotice(`“${item[0]}”待补充店铺凭证后即可创建采集草稿`)
